// Build a MissionSpec file + CLI args from the incoming plan.
// Expects: { spec_path?, spec?, knobs?, stages?, dry_run? }
const body = items[0].json;
const fs = require('fs');
const os = require('os');
const path = require('path');

let specPath = body.spec_path;
if (!specPath && body.spec) {
  specPath = path.join(os.tmpdir(), `sat_spec_${Date.now()}.json`);
  fs.writeFileSync(specPath, JSON.stringify(body.spec));
}
if (!specPath) {
  throw new Error('satellite specialist needs spec_path or spec');
}

const args = ['run', 'satellite', '--spec', specPath];
if (body.knobs) { args.push('--knobs', JSON.stringify(body.knobs)); }
if (Array.isArray(body.stages) && body.stages.length) { args.push('--stages', ...body.stages); }
if (body.dry_run) { args.push('--dry-run'); }

return [{ json: { argv: args.join(' '), runner: $env.CESAROPS_RUNNER || '/home/cesarops/wreckhunter2000-1/n8n/pipeline_runner.sh' } }];

// Parse the MissionReport JSON from stdout and surface candidates.
const out = items[0].json.stdout || '{}';
let report;
try { report = JSON.parse(out); } catch (e) { return [{ json: { error: 'bad JSON from sat-run', raw: out.slice(0, 500) } }]; }
const cands = report.candidates || [];
return [{ json: {
  pipeline: 'satellite',
  status: report.status,
  mission_id: report.mission_id,
  runtime_seconds: report.runtime_seconds,
  n_candidates: cands.length,
  top: cands.slice(0, 10),
  report
} }];
